import React from 'react'
import type {BypassActor} from '@github-ui/bypass-actors/types'
import {BypassManager} from '@github-ui/bypass-actors/BypassManager'
import {verifiedFetch} from '@github-ui/verified-fetch'
import {FlashError} from '@github-ui/flash-error'

const bypassActorsAreEqual = (a: BypassActor, b: BypassActor) => {
  return a.actorId === b.actorId && a.actorType === b.actorType
}

export interface SecretScanningPushProtectionBypassersListPartialProps {
  bypassers: BypassActor[]
  baseAvatarUrl: string
  suggestedBypassersUrl: string
  updateBypassActorUrl: string
  removeBypassActorUrl: string
  hidePlaceholderClassOnLoad?: string
  readOnly?: boolean
}

// This partial is used just on the Advanced Security settings page for repos. It wraps PushProtectionBypassersList.
export function SecretScanningPushProtectionBypassersListPartial({
  bypassers,
  baseAvatarUrl,
  suggestedBypassersUrl,
  updateBypassActorUrl,
  removeBypassActorUrl,
  hidePlaceholderClassOnLoad,
  readOnly = false,
}: SecretScanningPushProtectionBypassersListPartialProps) {
  const [error, setError] = React.useState<string | null>(null)

  // There's a spinner placeholder in the HTML by default, which we want to remove once the component loads.
  React.useEffect(() => {
    if (!hidePlaceholderClassOnLoad) {
      return
    }
    const placeholders = document.getElementsByClassName(hidePlaceholderClassOnLoad)
    for (const placeholder of placeholders) {
      placeholder.remove()
    }
  }, [hidePlaceholderClassOnLoad])

  // The callbacks here do an old-fashioned roundtrip form post, to fit in with the Advanced Security settings page
  // for repos.

  function handleResponse(resp: Response) {
    // the controller method will probably redirect us (302); we don't want to consider that an error
    if (resp.status >= 400 && resp.status < 600) {
      setError('Failed to update bypass actor.')
      return
    }
    if (resp.status === 302) {
      const loc = resp.headers.get('Location')
      if (loc) {
        window.location.href = loc
      }
    }
    window.location.reload()
  }

  async function updateBypassActor(bypassActor: BypassActor) {
    setError(null)

    const index = bypassers.findIndex((b: BypassActor) => bypassActorsAreEqual(b, bypassActor))
    if (index === -1) {
      return
    }
    const updatedBypassers = [...bypassers.slice(0, index), bypassActor, ...bypassers.slice(index + 1)]

    const formData = new FormData()
    let bypasserIndex = 0
    for (const updatedBypasser of updatedBypassers) {
      formData.set(`bypassers[${bypasserIndex}][actor_id]`, updatedBypasser.actorId?.toString() || '')
      formData.set(`bypassers[${bypasserIndex}][actor_type]`, updatedBypasser.actorType)
      formData.set(`bypassers[${bypasserIndex}][bypass_mode]`, updatedBypasser.bypassMode.toString())
      bypasserIndex += 1
    }

    const resp = await verifiedFetch(updateBypassActorUrl, {method: 'PUT', body: formData, redirect: 'manual'})
    handleResponse(resp)
  }

  async function removeBypassActor(bypassActor: BypassActor) {
    setError(null)

    const formData = new FormData()
    formData.set('bypass_reviewer_id', bypassActor.id?.toString() || '')
    const resp = await verifiedFetch(removeBypassActorUrl, {method: 'DELETE', body: formData, redirect: 'manual'})
    handleResponse(resp)
  }

  return (
    <>
      {error && <FlashError prefix="" errorMessageNotUsingPrefix={error} />}
      <BypassManager
        bypassers={bypassers}
        baseAvatarUrl={baseAvatarUrl}
        suggestedBypassersUrl={suggestedBypassersUrl}
        updateBypassActor={updateBypassActor}
        removeBypassActor={removeBypassActor}
        noSideMargins
        readOnly={readOnly}
      />
    </>
  )
}
